#!/usr/bin/env python3
"""Postrun evidence tables only; never modifies/reruns Lean or imputes missing costs."""
import argparse,collections,csv,json,pathlib,statistics
K={'Cslib.Tactic.PolyTime.tacticPolytime':'polytime','Mathlib.Meta.FunProp.funPropTacStx':'fun_prop','Cslib.Tactic.PPT.tacticPpt':'ppt'}
def main(out,static):
 attempts=json.loads((out/'attempts.json').read_text());commands=json.loads((out/'commands.json').read_text());plan=json.loads((out/'plan.json').read_text());tokens=json.loads((static/'index/all-target-tokens.json').read_text());index={t['call_id']:t for t in tokens};grid={(c['path'],c['mode']):c for c in commands}
 def good(path,mode):
  c=grid.get((path,mode));return c is not None and c['returncode']==0 and c.get('external_warning_acceptance',False) and c['context_error'] is None and c['actual_context'] is not None
 fields=['event_id','mode','path','tactic','static_head_id','runtime_full_syntax_id','mapping','source_url','module','declaration','status','goals_before','goals_after','maxHeartbeats_user','remaining_raw_heartbeats','maxRecDepth','async_option','raw_body_thread_heartbeats','body_user_heartbeat_units','raw_region_thread_heartbeats','body_wall_nanoseconds','same_thread_endpoints','original_file_acceptance','mode_acceptance','primary_returned_closed_goal_cost_eligible','goal_heads_json']
 rows=[];eligible=[]
 for a in attempts:
  b=a['begin'];e=a.get('end') or {};t=index.get(a['static_head_id'],{});original_ok=good(a['path'],'baseline');mode_ok=good(a['path'],a['mode']);primary=bool(a['mode']=='measured' and a['static_head_id'] and original_ok and good(a['path'],'import-only') and mode_ok and a['status']=='returned' and e.get('goals_after')==0 and a['raw_body_thread_heartbeats'] is not None)
  row={k:a.get(k) for k in ('event_id','mode','path','static_head_id','runtime_full_syntax_id','mapping','status','raw_body_thread_heartbeats','body_user_heartbeat_units','body_wall_nanoseconds')};row.update(tactic=K[b['kind']],source_url=t.get('url'),module=b.get('module'),declaration=b.get('declaration'),goals_before=b.get('goals_before'),goals_after=e.get('goals_after'),maxHeartbeats_user=b.get('maxHeartbeats_user'),remaining_raw_heartbeats=b.get('remaining_raw_heartbeats'),maxRecDepth=b.get('maxRecDepth'),async_option=b.get('async_option'),raw_region_thread_heartbeats=e.get('raw_region_thread_heartbeats'),same_thread_endpoints=e.get('same_thread'),original_file_acceptance=original_ok,mode_acceptance=mode_ok,primary_returned_closed_goal_cost_eligible=primary,goal_heads_json=json.dumps(b.get('goal_heads',[]),ensure_ascii=False));rows.append(row)
  if primary:eligible.append(row)
 with (out/'attempt-metrics.csv').open('w',newline='') as stream:
  writer=csv.DictWriter(stream,fieldnames=fields,lineterminator='\n');writer.writeheader();writer.writerows(rows)
 candidates={h for f in plan['files'] for h in f['candidate_head_ids']};observed={a['static_head_id'] for a in attempts if a['mode']=='measured' and a['static_head_id']};not_seen=sorted(candidates-observed);args={h for h in candidates if index[h]['source_form']=='explicit-arguments'}
 def stats(rs):
  hb=[r['body_user_heartbeat_units'] for r in rs];return {'returned_closed_goal_attempts':len(rs),'distinct_authored_heads':len({r['static_head_id'] for r in rs}),'median_instrumented_body_user_hb':statistics.median(hb) if hb else None,'max_instrumented_body_user_hb':max(hb) if hb else None}
 heads=collections.Counter();authored_heads=collections.Counter();other_heads=collections.Counter()
 for a in attempts:
  if a['mode']=='measured':
   for h in a['begin'].get('goal_heads',[]):
    name=h.get('head_after_foralls_mdata') or '<no constant head>';heads[name]+=1
    (authored_heads if a['static_head_id'] else other_heads)[name]+=1
 report={'pin':plan['pin'],'protocol':'original Lake options, separately instrumented diagnostic bodies','files':len(plan['files']),'commands':len(commands),'all_four_modes_accepted_files':sum(all(good(f['path'],m) for m in ('baseline','import-only','measured','traced')) for f in plan['files']),'baseline_import_measured_accepted_files':sum(all(good(f['path'],m) for m in ('baseline','import-only','measured')) for f in plan['files']),'failed_commands':[{'path':c['path'],'mode':c['mode'],'process_returncode':c['returncode'],'external_warning_acceptance':c.get('external_warning_acceptance'),'context_error':c['context_error']} for c in commands if not good(c['path'],c['mode'])],'static_authored_candidates':len(candidates),'measured_observed_distinct_authored_heads':len(observed),'not_observed_authored_heads':len(not_seen),'explicit_argument_static_candidates':len(args),'explicit_argument_observed_heads':len(args&observed),'measured_attempt_statuses':dict(collections.Counter(a['status'] for a in attempts if a['mode']=='measured')),'measured_mapping_counts':dict(collections.Counter(a['mapping'] for a in attempts if a['mode']=='measured')),'measured_syntactic_goal_heads':dict(heads),'measured_authored_syntactic_goal_heads':dict(authored_heads),'measured_other_syntactic_goal_heads':dict(other_heads),'primary_returned_closed_goal_costs':{t:stats([r for r in eligible if r['tactic']==t]) for t in K.values()},'qualification':'One pass/mode; not minimum budgets or program runtimes. Primary costs require exact authored mapping, original baseline/import/measured whole-file acceptance, returned zero-goal observation, and available endpoint-same-thread raw HB. Exceptions/censored/generated/unobserved remain separate. Inclusive nested costs and shared-host wall are not additive. Returned is not final proof attribution. Native trace messages are attempts/retained diagnostics, not a final proof rule ledger. No costs transferred from warning-strict/historical pins.'}
 (out/'coverage-synthesis.json').write_text(json.dumps(report,indent=2,ensure_ascii=False)+'\n');(out/'not-observed-authored-heads.json').write_text(json.dumps([index[h] for h in not_seen],indent=2,ensure_ascii=False)+'\n');print(json.dumps({k:report[k] for k in ('files','commands','all_four_modes_accepted_files','baseline_import_measured_accepted_files','measured_observed_distinct_authored_heads','not_observed_authored_heads')}))
if __name__=='__main__':
 p=argparse.ArgumentParser();p.add_argument('out',type=pathlib.Path);p.add_argument('--static',type=pathlib.Path,required=True);a=p.parse_args();main(a.out,a.static)
